//! Owned, serializable data model for a profile.
//!
//! These types form the on-disk schema. They are archived via rkyv and
//! consumed through the typed view in [`crate::Profile`].

use indexmap::IndexMap;
use rkyv::{Archive, Deserialize, Serialize};

/// Version of the profile format described by this module.
///
/// Bumped whenever the archived layout or the meaning of its contents
/// changes, so that profiles generated by an older version can be detected
/// and rebuilt instead of being used with missing data.
///
/// Version 1 added [`Profile::version`], [`Profile::functions`] and the
/// naming of anonymous DWARF types after the typedef that declares them.
pub const FORMAT_VERSION: u32 = 1;

/// A full profile: architecture, type definitions, symbols, segments and
/// function prototypes.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct Profile {
    /// Profile format version, [`FORMAT_VERSION`] for profiles generated by
    /// this version of the crate.
    ///
    /// Profiles generated before the version was recorded deserialize from
    /// JSON with version 0.
    #[cfg_attr(feature = "serde", serde(default))]
    pub version: u32,

    /// Target architecture.
    pub architecture: Architecture,

    /// Enum definitions keyed by name.
    pub enums: IndexMap<String, Enum>,

    /// Struct definitions keyed by name.
    pub structs: IndexMap<String, Struct>,

    /// Symbol RVAs keyed by symbol name.
    pub symbols: IndexMap<String, u64>,

    /// Image segments keyed by segment name.
    ///
    /// Profiles generated from formats without a segment table leave this
    /// map empty.
    #[cfg_attr(feature = "serde", serde(default))]
    pub segments: IndexMap<String, Segment>,

    /// Function prototypes indexed by symbol name.
    ///
    /// The key is the linkage name when the debug information records one,
    /// for example the mangled name of a C++ method, and the source name
    /// otherwise, so it matches the key of the function in
    /// [`Profile::symbols`]. Profiles generated from formats without
    /// prototypes leave this map empty.
    #[cfg_attr(feature = "serde", serde(default))]
    pub functions: IndexMap<String, Function>,
}

impl Default for Profile {
    /// Returns an empty profile of the current [`FORMAT_VERSION`].
    fn default() -> Self {
        Self {
            version: FORMAT_VERSION,
            architecture: Architecture::default(),
            enums: IndexMap::new(),
            structs: IndexMap::new(),
            symbols: IndexMap::new(),
            segments: IndexMap::new(),
            functions: IndexMap::new(),
        }
    }
}

/// Function prototype.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct Function {
    /// Return type, [`Base::Void`] for functions without a result.
    pub return_type: Type,

    /// Parameters in declaration order.
    ///
    /// Hidden parameters the compiler records, such as the `this` pointer
    /// of a C++ method, are included.
    pub parameters: Vec<Parameter>,

    /// Whether the function takes a variable number of arguments after
    /// `parameters`.
    pub variadic: bool,
}

/// Function parameter.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct Parameter {
    /// Parameter name, `None` if the debug information does not record
    /// one, for example in a declaration.
    pub name: Option<String>,

    /// Parameter type.
    #[cfg_attr(feature = "serde", serde(rename = "type"))]
    pub ty: Type,
}

/// Name prefix of struct and union members without a name.
///
/// Profile generators name an anonymous member, such as a C11 anonymous
/// union inside a struct, with this prefix followed by a number that keeps
/// the names of several anonymous members of one struct apart.
pub const ANONYMOUS_FIELD_PREFIX: &str = "__unnamed_field_";

/// Image segment.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct Segment {
    /// Start address of the segment, using the same base as symbol values.
    pub address: u64,

    /// Size of the segment in bytes.
    pub size: u64,
}

/// Target CPU architecture.
#[derive(Debug, Default, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub enum Architecture {
    /// Unknown or unspecified architecture.
    #[default]
    Unknown,

    /// 32-bit x86.
    X86,

    /// 64-bit x86.
    Amd64,

    /// 32-bit ARM.
    Arm32,

    /// 64-bit ARM.
    Arm64,
}

//
// Enum
//

/// Enum type.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct Enum {
    /// Underlying integer type of the enum.
    pub subtype: Type,

    /// Enum variants keyed by name.
    pub fields: IndexMap<String, Variant>,
}

/// Enum variant.
#[allow(missing_docs)]
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(
    feature = "serde",
    derive(serde::Serialize, serde::Deserialize),
    serde(untagged)
)]
#[rkyv(derive(Debug))]
pub enum Variant {
    U8(u8),
    U16(u16),
    U32(u32),
    U64(u64),
    U128(u128),
    I8(i8),
    I16(i16),
    I32(i32),
    I64(i64),
    I128(i128),
}

//
// Struct
//

/// Struct type.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct Struct {
    /// Struct / class / union / interface tag.
    pub kind: StructKind,

    /// Size of the struct in bytes.
    pub size: u64,

    /// Fields keyed by name.
    pub fields: IndexMap<String, Field>,
}

/// Struct kind.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(
    feature = "serde",
    derive(serde::Serialize, serde::Deserialize),
    serde(rename_all = "snake_case")
)]
#[rkyv(derive(Debug))]
pub enum StructKind {
    /// A `struct`.
    Struct,

    /// A `class`.
    Class,

    /// A `union`.
    Union,

    /// An `interface`.
    Interface,
}

/// Struct field.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct Field {
    /// Field offset (in bytes).
    pub offset: u64,

    /// Field type.
    #[cfg_attr(feature = "serde", serde(rename = "type"))]
    pub ty: Type,
}

//
// Type
//

/// Type.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(
    feature = "serde",
    derive(serde::Serialize, serde::Deserialize),
    serde(rename_all = "snake_case", tag = "kind")
)]
#[rkyv(derive(Debug))]
pub enum Type {
    /// Base type.
    Base(Base),

    /// Enum type.
    Enum(EnumRef),

    /// Struct type.
    Struct(StructRef),

    /// Array type.
    Array(Array),

    /// Pointer type.
    Pointer(Pointer),

    /// Bitfield type.
    Bitfield(Bitfield),

    /// Function type.
    Function,
}

/// Base type.
#[allow(missing_docs)]
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(
    feature = "serde",
    derive(serde::Serialize, serde::Deserialize),
    serde(rename_all = "snake_case", tag = "subkind")
)]
#[rkyv(derive(Debug))]
pub enum Base {
    /// Void type.
    Void,

    /// Boolean type.
    Bool,

    /// Character types.
    Char8,
    Char16,
    Char32,

    /// Signed integer types.
    I8,
    I16,
    I32,
    I64,
    I128,

    /// Unsigned integer types.
    U8,
    U16,
    U32,
    U64,
    U128,

    /// Floating-point types.
    F8,
    F16,
    F32,
    F64,
    F128,
}

impl Base {
    /// Returns the size of the base type in bytes.
    pub fn size(&self) -> u64 {
        match self {
            Self::Void => 0,
            Self::Char8 | Self::I8 | Self::U8 | Self::F8 | Self::Bool => 1,
            Self::Char16 | Self::I16 | Self::U16 | Self::F16 => 2,
            Self::Char32 | Self::I32 | Self::U32 | Self::F32 => 4,
            Self::I64 | Self::U64 | Self::F64 => 8,
            Self::I128 | Self::U128 | Self::F128 => 16,
        }
    }
}

impl ArchivedBase {
    /// Returns the size of the base type in bytes.
    pub fn size(&self) -> u64 {
        match self {
            Self::Void => 0,
            Self::Char8 | Self::I8 | Self::U8 | Self::F8 | Self::Bool => 1,
            Self::Char16 | Self::I16 | Self::U16 | Self::F16 => 2,
            Self::Char32 | Self::I32 | Self::U32 | Self::F32 => 4,
            Self::I64 | Self::U64 | Self::F64 => 8,
            Self::I128 | Self::U128 | Self::F128 => 16,
        }
    }
}

/// Enum reference.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct EnumRef {
    /// Name of the referenced enum.
    pub name: String,
}

/// Struct reference.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(derive(Debug))]
pub struct StructRef {
    /// Name of the referenced struct.
    pub name: String,
}

/// Array type.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(
    derive(Debug),
    serialize_bounds(
        __S: rkyv::ser::Writer + rkyv::ser::Allocator,
        __S::Error: rkyv::rancor::Source,
    ),
    deserialize_bounds(
        __D::Error: rkyv::rancor::Source,
    ),
    bytecheck(bounds(
        __C: rkyv::validation::ArchiveContext,
        __C::Error: rkyv::rancor::Source,
    )
))]
pub struct Array {
    /// Element type.
    #[rkyv(omit_bounds)]
    pub subtype: Box<Type>,

    /// Array dimensions.
    pub dims: Vec<u64>,
}

/// Bitfield type.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(
    derive(Debug),
    serialize_bounds(
        __S: rkyv::ser::Writer + rkyv::ser::Allocator,
        __S::Error: rkyv::rancor::Source,
    ),
    deserialize_bounds(
        __D::Error: rkyv::rancor::Source,
    ),
    bytecheck(bounds(
        __C: rkyv::validation::ArchiveContext,
        __C::Error: rkyv::rancor::Source,
    )
))]
pub struct Bitfield {
    /// Bitfield subtype.
    #[rkyv(omit_bounds)]
    pub subtype: Box<Type>,

    /// Bit length.
    pub bit_length: u64,

    /// Bit position.
    pub bit_position: u64,
}

/// Pointer type.
#[derive(Debug, Archive, Serialize, Deserialize)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[rkyv(
    derive(Debug),
    serialize_bounds(
        __S: rkyv::ser::Writer + rkyv::ser::Allocator,
        __S::Error: rkyv::rancor::Source,
    ),
    deserialize_bounds(
        __D::Error: rkyv::rancor::Source,
    ),
    bytecheck(bounds(
        __C: rkyv::validation::ArchiveContext,
        __C::Error: rkyv::rancor::Source,
    )
))]
pub struct Pointer {
    /// Type of the pointed value.
    #[rkyv(omit_bounds)]
    pub subtype: Box<Type>,

    /// Size of the pointer in bytes.
    pub size: u64,
}
